    s->last_id = id;
    if (added_id) *added_id = id;
    return C_OK;
}

/* Trims a stream by length. Returns the number of deleted items. */
int64_t streamTrimByLength(stream *s, long long maxlen, int approx) {
    streamAddTrimArgs args = {
        .trim_strategy = TRIM_STRATEGY_MAXLEN,
        .approx_trim = approx,
        .limit = approx ? 100 * server.stream_node_max_entries : 0,
        .maxlen = maxlen
    };
    robj subject;
    subject.type = OBJ_STREAM;
    subject.encoding = OBJ_ENCODING_STREAM;
    subject.lru = 0;
    subject.refcount = OBJ_STATIC_REFCOUNT;
    subject.ptr = s;
    return streamTrim(&subject, &args, args.limit);
}

